/**
 * 校验要件文件，通过返回空串，否则返回错误提示
 * @param {File} file
 * @param {string[]} [allowedExtensions] 按要件配置推导的允许扩展名；为空时回落到默认清单
 * @returns {string}
 */
export function validateAppendixFile(file, allowedExtensions) {
  if (!file) return '请选择要上传的文件'
  if (!file.size) return APPENDIX_EMPTY_FILE_TIP
  const allowed = Array.isArray(allowedExtensions) && allowedExtensions.length
    ? allowedExtensions
    : APPENDIX_ACCEPT_EXTENSIONS
  if (!allowed.includes(getFileExtension(file.name))) {
    return allowed === APPENDIX_ACCEPT_EXTENSIONS
      ? APPENDIX_FILE_TYPE_ERROR
      : `仅支持上传${toFormatText(allowed)}格式的文件`
  }
  if (file.size > APPENDIX_MAX_FILE_SIZE) {
    return '上传文件大小不能超过5MB'
  }
  return ''
}

