/**
 * 要件组件：上传前校验。
 * 允许扩展名按当前要件的 fileType 命中 file_type 字典 remark 推导（如委托授权书含 .doc/.docx）；
 * 推导为空时回落到默认清单（.png/.jpg/.pdf）。避免出现「提示支持 word、上传却被拦截」的口径错位。
 */
handleRequirementBeforeUpload(file, item) {
  const allowedExtensions = resolveAllowedExtensions(item && item.fileType, this.fileTypeOptions)
  const message = validateAppendixFile(file, allowedExtensions)
  if (message) {
    this.msgError(message)
    return false
  }
  return true
},

