tool_input.new_string:
uploadTip() {
  if (!this.visibleAppendixConfigs.length) return ''
  // 汇总各要件配置的允许类型，无字典/未命中时回落到默认口径
  const set = new Set()
  this.visibleAppendixConfigs.forEach((config) => {
    resolveAllowedExtensions(config.fileType, this.fileTypeOptions).forEach((ext) => set.add(ext))
  })
  const types = set.size ? Array.from(set).map((ext) => `.${ext}`).join('、') : '.png、.jpg、.pdf'
  return `支持${types}，单个文件不超过5MB`
},

